SELECT --DISTINCT JT.codAtributoPIM
   -- COUNT(*)
   -- *
    ID_MODELO
FROM EDSR.PIM_MODELO T
            ,JSON_TABLE( T.CONTENIDO, '$.productos[*]' COLUMNS (codAtributoPIM VARCHAR2(100) PATH '$.codAtributoPIM',
                                                                ValorModificado VARCHAR2(100) PATH '$.ValorModificado')
            ) JT
WHERE  FLG_PROCESADO = '0' AND ID_TIPO = '3' --AND FLG_ERROR = '0'
    AND JT.codAtributoPIM IS NOT NULL
    --AND jt.ValorModificado = 'MALLA ELECTROSOLDADA 10-15'
   -- FETCH FIRST 200 ROWS ONLY;
;

SELECT * FROM EDSR.PIM_MODELO M WHERE ID_TIPO IN (3) AND FLG_PROCESADO = '0' ORDER BY FEC_CREACION DESC;

SELECT
   --* -- COUNT(*)
    PIM.*
FROM EDSR.PIM_MODELO PIM
    ,JSON_TABLE(PIM.CONTENIDO,
                '$.productos[*]'
                COLUMNS (IdPim VARCHAR2(15) PATH '$.IdPim',
                        NombreProducto VARCHAR2(100) PATH '$.NombreProducto',
                        SKU VARCHAR2(8) PATH '$.sku',
                        CodigoAtributo VARCHAR2(50) PATH '$.codAtributoPIM',
                        ValorModificado VARCHAR2(120) PATH '$.ValorModificado')
                ) JSON
WHERE JSON.ValorModificado IS NOT NULL
    AND JSON.IdPim = 'HESA_40921'
    AND PIM.FEC_CREACION >= TO_DATE('2024-10-16', 'YYYY-MM-DD')
    AND PIM.FEC_CREACION < TO_DATE('2024-10-17', 'YYYY-MM-DD')
ORDER BY JSON.CodigoAtributo
;





