-- CONSULTAR
SELECT
   -- *
   --COUNT(*)
   -- PIM.*
   -- DISTINCT JSON.CodigoAtributo
    --JSON.*
    JSON.IdPim,
    COUNT(JSON.IdPim) AS total
FROM EDSR.PIM_MODELO PIM
    ,JSON_TABLE(
        PIM.MENSAJE,
        '$' COLUMNS (
            IdPim VARCHAR2(15) PATH '$.id_pim',
            CodigoAtributo VARCHAR2(100) PATH '$.CodAtributo',
            Valor VARCHAR2(500) PATH '$.valorAtributo'
        )
    ) JSON
WHERE PIM.ID_TIPO = 4 AND FLG_PROCESADO = '0' AND PIM.MENSAJE IS NOT NULL
    --  AND JSON.Valor IS NULL
    --  AND JSON.IdPim = 'HESA_40921'
    --  AND PIM.FEC_CREACION >= TO_DATE('2024-10-16', 'YYYY-MM-DD')
    --  AND PIM.FEC_CREACION < TO_DATE('2024-10-17', 'YYYY-MM-DD')
GROUP BY JSON.IdPim
ORDER BY Total DESC
--ORDER BY JSON.CodigoAtributo
;

